using DriveOS.Application.Abstractions.Messaging;
using DriveOS.Application.Abstractions.Time;
using DriveOS.Modules.Workforce.Application.Persistence;
using DriveOS.Modules.Workforce.Domain.Employees;
using DriveOS.Modules.Workforce.Domain.Timesheets;
using DriveOS.SharedKernel.Identifiers;
using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.Workforce.Application.Timesheets;

public sealed class CreateTimesheetCommandHandler(ITimesheetRepository repo,IEmployeeRepository employees,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<CreateTimesheetCommand,TimesheetId>
{
 public async Task<Result<TimesheetId>> Handle(CreateTimesheetCommand c,CancellationToken ct){var employee=await employees.GetByIdAsync(c.OrganizationId,c.EmployeeId,ct);if(employee is null)return Result.Failure<TimesheetId>(EmployeeErrors.NotFound);if(c.PeriodFrom<employee.EmploymentStartDate||(employee.EmploymentEndDate is DateOnly end&&c.PeriodTo>end))return Result.Failure<TimesheetId>(TimesheetErrors.InvalidPeriod);if(await repo.HasOverlapAsync(c.OrganizationId,c.EmployeeId,c.PeriodFrom,c.PeriodTo,null,ct))return Result.Failure<TimesheetId>(TimesheetErrors.OverlappingPeriod);var r=Timesheet.Create(c.TimesheetId,c.OrganizationId,c.EmployeeId,c.PeriodFrom,c.PeriodTo,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return Result.Failure<TimesheetId>(r.Error);repo.Add(r.Value);await uow.CommitAsync(ct);return Result.Success(r.Value.Id);}
}
public sealed class AddTimesheetEntryCommandHandler(ITimesheetRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<AddTimesheetEntryCommand,TimesheetEntryId>
{public async Task<Result<TimesheetEntryId>> Handle(AddTimesheetEntryCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.TimesheetId,true,ct);if(x is null)return Result.Failure<TimesheetEntryId>(TimesheetErrors.NotFound);var r=x.AddEntry(c.EntryId,c.Date,c.ActivityType,c.Hours,c.Description,c.Source,c.SourceReference,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return Result.Failure<TimesheetEntryId>(r.Error);await uow.CommitAsync(ct);return r;}}
public sealed class UpdateTimesheetEntryCommandHandler(ITimesheetRepository repo,IWorkforceUnitOfWork uow,IClock clock):ICommandHandler<UpdateTimesheetEntryCommand>
{public async Task<Result> Handle(UpdateTimesheetEntryCommand c,CancellationToken ct){var x=await repo.GetAsync(c.OrganizationId,c.TimesheetId,true,ct);if(x is null)return Result.Failure(TimesheetErrors.NotFound);var r=x.UpdateEntry(c.EntryId,c.Date,c.ActivityType,c.Hours,c.Description,clock.UtcNow,c.ActorUserId);if(r.IsFailure)return r;await uow.CommitAsync(ct);return Result.Success();}}
