public sealed class GetTimesheetQueryHandler(ITimesheetRepository repo):IQueryHandler<GetTimesheetQuery,TimesheetResponse>
{public async Task<Result<TimesheetResponse>> Handle(GetTimesheetQuery q,CancellationToken ct){var x=await repo.GetAsync(q.OrganizationId,q.TimesheetId,false,ct);return x is null?Result.Failure<TimesheetResponse>(TimesheetErrors.NotFound):Result.Success(Map(x));}internal static TimesheetResponse Map(Timesheet x)=>new(x.Id.Value,x.EmployeeId.Value,x.PeriodFrom,x.PeriodTo,x.Status.ToString(),x.TotalHours,x.SubmittedAtUtc,x.SubmittedByUserId?.Value,x.ReviewStartedAtUtc,x.ReviewerUserId?.Value,x.DecidedAtUtc,x.DecidedByUserId?.Value,x.DecisionReason,x.LockedAtUtc,x.LockedByUserId?.Value,x.Entries.OrderBy(e=>e.Date).ThenBy(e=>e.Id.Value).Select(e=>new TimesheetEntryResponse(e.Id.Value,e.Date,e.ActivityType.ToString(),e.Hours,e.Description,e.Source.ToString(),e.SourceReference)).ToArray());}
public sealed class GetTimesheetsQueryHandler(ITimesheetRepository repo):IQueryHandler<GetTimesheetsQuery,IReadOnlyList<TimesheetResponse>>{public async Task<Result<IReadOnlyList<TimesheetResponse>>> Handle(GetTimesheetsQuery q,CancellationToken ct)=>Result.Success<IReadOnlyList<TimesheetResponse>>((await repo.ListAsync(q.OrganizationId,q.EmployeeId,q.Status,q.From,q.To,ct)).Select(GetTimesheetQueryHandler.Map).ToArray());}
